fn opposite_trailing_slash_path(&self, path: &str) -> String {
    if let Some(without_tsr) = path.strip_suffix('/') {
        without_tsr.to_owned()
    } else {
        format!("{}/", path)
    }
}

fn opposite_trailing_slash_uri(&self, uri: &Uri, path: &str) -> Uri {
    let redirected_path = self.opposite_trailing_slash_path(path);
    self.with_replaced_path(uri, &redirected_path)
}

fn redirect_trailing_slash(&self, redirect_to: Uri) -> Response {
    self.build_redirect_response(self.trailing_slash_status, redirect_to)
}

fn build_redirect_response(&self, status: StatusCode, redirect_to: Uri) -> Response {
    let mut builder = Response::builder().status(status);
    builder = self.attach_location_header(builder, &redirect_to);
    builder.body(crate::body::empty()).unwrap()
}

